function Btn({children,variant,v,size,sz,onClick,full=false,style={},disabled=false}) {
  const resolvedVariant = variant || v || "teal";
  const resolvedSize = size || sz || "md";
  const szMap = {sm:{padding:"7px 16px",fontSize:11},md:{padding:"11px 22px",fontSize:13},lg:{padding:"15px 32px",fontSize:15}};
  const vs = {
    primary:{background:`linear-gradient(135deg,${C.teal},${C.tealDim})`,color:C.navy,boxShadow:`0 4px 18px ${C.teal}30`,border:"none"},
    teal:{background:`linear-gradient(135deg,${C.teal},${C.tealDim})`,color:C.navy,boxShadow:`0 4px 18px ${C.teal}30`,border:"none"},
    gold:{background:`linear-gradient(135deg,${C.gold},${C.goldDim})`,color:C.navy,boxShadow:`0 4px 18px ${C.gold}30`,border:"none"},
    ghost:{background:"transparent",color:C.teal,border:`1.5px solid ${C.teal}55`},
    outline:{background:"transparent",color:C.text,border:`1.5px solid ${C.navyBord}`},
    dark:{background:C.navyCard,color:C.text,border:`1.5px solid ${C.navyBord}`},
    danger:{background:"transparent",color:C.danger,border:`1.5px solid ${C.danger}55`},
    purple:{background:`linear-gradient(135deg,${C.purple},#5a3fd4)`,color:"#fff",border:"none",boxShadow:`0 4px 18px ${C.purple}30`},
  };
  return (
    <button disabled={disabled} onClick={onClick}
      style={{display:"inline-flex",alignItems:"center",justifyContent:full?"center":"flex-start",gap:8,borderRadius:10,fontFamily:"'Space Grotesk'",fontWeight:600,transition:"all .18s",width:full?"100%":"auto",opacity:disabled?0.5:1,cursor:disabled?"not-allowed":"pointer",...szMap[resolvedSize],...vs[resolvedVariant],...style}}
      onMouseEnter={e=>{if(!disabled)e.currentTarget.style.transform="translateY(-1px)";}}
      onMouseLeave={e=>{e.currentTarget.style.transform="translateY(0)";}}>
      {children}
    </button>
  );
};

function Card({children,style={},glow=false,hover=false,onClick}) {
  const [hov,setHov] = useState(false);
  return (
    <div onClick={onClick}
      onMouseEnter={()=>hover&&setHov(true)} onMouseLeave={()=>setHov(false)}
      style={{background:C.navyCard,border:`1px solid ${hov?C.navyBord+"99":C.navyBord}`,borderRadius:14,padding:20,height:"100%",boxSizing:"border-box",display:"flex",flexDirection:"column",boxShadow:glow?`0 0 30px ${C.teal}15,0 4px 20px #00000030`:"0 2px 12px #00000025",cursor:onClick?"pointer":"default",transition:"transform .18s, box-shadow .18s",transform:hov&&hover?"translateY(-2px)":"translateY(0)",...style}}>
      {children}
    </div>
  );
};

const Field = ({label,type="text",placeholder,value,onChange,error,prefix}) => (
  <div style={{marginBottom:16}}>
    {label&&<label style={{display:"block",marginBottom:5,fontSize:11,color:C.muted,fontWeight:500}}>{label}</label>}
    <div style={{position:"relative"}}>
      {prefix&&<div style={{position:"absolute",left:11,top:"50%",transform:"translateY(-50%)"}}>{prefix}</div>}
      <input type={type} placeholder={placeholder} value={value} onChange={e=>onChange(e.target.value)}
        style={{width:"100%",background:C.navyMid,border:`1.5px solid ${error?C.danger:C.navyBord}`,borderRadius:9,padding:`10px ${prefix?"38px":"13px"}`,color:C.text,fontSize:13,transition:"border .2s"}}
        onFocus={e=>e.target.style.borderColor=C.teal} onBlur={e=>e.target.style.borderColor=error?C.danger:C.navyBord}/>
    </div>
    {error&&<p style={{marginTop:3,fontSize:10,color:C.danger}}>{error}</p>}
  </div>
);

const Divider = () => <div style={{height:1,background:C.navyBord,margin:"4px 0"}}/>;

const StatPill = ({label,value,color=C.teal}) => (
  <div style={{textAlign:"center"}}>
    <div style={{fontSize:25,fontWeight:700,fontFamily:"'Space Grotesk'",color,letterSpacing:"-.02em"}}>{value}</div>
    <div style={{fontSize:10,color:C.muted,marginTop:3}}>{label}</div>
  </div>
);

const SectionLabel = ({children}) => (
  <div style={{fontSize:10,fontWeight:600,letterSpacing:".1em",textTransform:"uppercase",color:C.dim,marginBottom:16}}>{children}</div>
);

function homeownerDefaults(user) {
  return {
    ...user,
    avatar: user.avatar || (user.name||"").split(" ").map(w=>w[0]).join("").toUpperCase().slice(0,2),
    plan: user.plan || "HOMEOWNER_FREE",
    energy: user.energy || {solar:0,consumed:0,exported:0,saved:0},
    rewards: user.rewards || {points:0,tier:"Bronze",nextTier:"Silver",nextTierAt:500},
    wallet: user.wallet || {balance:0,pending:0,lifetime:0},
    referrals: user.referrals || 0,
    homeScore: user.homeScore || 0,
    weather: user.weather || {temp:70,condition:"Sunny",solarForecast:"Connect devices to see forecast",tomorrowForecast:""},
    aiInsight: user.aiInsight || {text:"Connect your first device to get personalized AI recommendations.",action:"Connect Device",savings:""},
    utility: {
      provider:"", bill:0, baseline:0, tariff:"", peakRate:0, offPeakRate:0, credits:0,
      savings:{monthly:0, annual:0},
      ...(user.utility||{}),
      savings: { monthly:0, annual:0, ...((user.utility||{}).savings||{}) },
    },
    devices: user.devices || [],
    vpp: user.vpp || {enrolled:false,ytd:0,history:[]},
    rebates: user.rebates || [],
    transactions: user.transactions || [],
    quotes: user.quotes || [],
  };
}


