function PortalGateway({nav, type, onEnterPortal=null}) {
  const isSeller = type === "seller";

  const accent  = isSeller ? C.gold : C.teal;
  const acDim   = isSeller ? C.goldDim : C.tealDim;
  const icon    = isSeller ? "store" : "tool";
  const title   = isSeller ? "Seller Portal" : "Installer Portal";
  const sub     = isSeller ? "Manage your listings, orders, and payouts" : "Manage your leads, jobs, and earnings";

  const [email,setEmail]   = useState("");
  const [pass,setPass]     = useState("");
  const [err,setErr]       = useState("");
  const [loading,setLoading] = useState(false);
  const {isMobile} = useBP();

  const login = async () => {
    if (!email || !pass) { setErr("Enter your email and password."); return; }
    setLoading(true); setErr("");
    try{
      const r = await fetch("/api/auth/login",{
        method:"POST", credentials:"include",
        headers:{"Content-Type":"application/json"},
        body: JSON.stringify({email,password:pass}),
      });
      const data = await r.json();
      const expectedRole = isSeller ? "SELLER" : "INSTALLER";
      if(!r.ok){ setErr(data.error||"Login failed"); return; }
      if(data.user.role!==expectedRole){ setErr(`This account is not registered as a${isSeller?" seller":"n installer"}.`); return; }
      if (onEnterPortal) onEnterPortal(type);
      else window.location.href = isSeller ? "/portals/seller" : "/portals/installer";
    }catch(e){ setErr("Network error — please try again."); }
    finally{ setLoading(false); }
  };

  return (
    <div style={{minHeight:"100vh", background:C.navy, paddingTop:62, display:"flex", alignItems:"center", justifyContent:"center", padding:"80px 20px 40px"}}>
      <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",padding:"0 0 0 0"}}>
        <button onClick={()=>nav("e-installers")}
          style={{display:"inline-flex",alignItems:"center",gap:6,background:"none",border:"none",cursor:"pointer",
            color:C.muted,fontSize:12,padding:"6px 10px",borderRadius:8,transition:"all .15s"}}
          onMouseEnter={e=>{e.currentTarget.style.background=C.navyCard;e.currentTarget.style.color=C.text;}}
          onMouseLeave={e=>{e.currentTarget.style.background="none";e.currentTarget.style.color=C.muted;}}>
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="15 18 9 12 15 6"/></svg>
          Back to Installers
        </button>
        <button onClick={()=>nav("e-home")}
          style={{width:32,height:32,borderRadius:8,background:C.navyCard,border:`1px solid ${C.navyBord}`,
            display:"flex",alignItems:"center",justifyContent:"center",cursor:"pointer",transition:"all .15s"}}
          onMouseEnter={e=>{e.currentTarget.style.borderColor=C.danger;}}
          onMouseLeave={e=>{e.currentTarget.style.borderColor=C.navyBord;}}>
          <Icon name="x" size={15} color={C.muted}/>
        </button>
      </div>
      <div style={{width:"100%", maxWidth:440}}>

        {/* Back link */}
        <button onClick={()=>nav(isSeller?"e-marketplace":"e-installers")}
          style={{display:"flex",alignItems:"center",gap:6,marginBottom:24,background:"none",border:"none",color:C.muted,fontSize:11,cursor:"pointer",padding:0}}>
          <Icon name="arrow" size={12} color={C.muted} style={{transform:"rotate(180deg)"}}/> Back to {isSeller?"Marketplace":"Installers"}
        </button>

        {/* Header */}
        <div style={{textAlign:"center", marginBottom:28}}>
          <div style={{width:60,height:60,borderRadius:16,background:`${accent}14`,border:`2px solid ${accent}30`,display:"flex",alignItems:"center",justifyContent:"center",margin:"0 auto 16px"}}>
            <Icon name={icon} size={26} color={accent}/>
          </div>
          <h1 style={{fontFamily:"'Space Grotesk'",fontSize:23,fontWeight:700,color:"#F0F4FF",marginBottom:6}}>{title}</h1>
          <p style={{color:C.muted,fontSize:12}}>{sub}</p>
        </div>

        {/* Login form */}
        <div style={{background:C.navyCard,border:`1px solid ${C.navyBord}`,borderRadius:14,padding:"22px"}}>
          {err&&(
            <div style={{background:"#FF4D6A10",border:"1px solid #FF4D6A30",borderRadius:8,padding:"9px 12px",marginBottom:14,fontSize:11,color:"#FF4D6A"}}>
              {err}
            </div>
          )}

          <label style={{display:"block",fontSize:10,color:C.muted,fontWeight:500,marginBottom:5}}>Email</label>
          <input value={email} onChange={e=>setEmail(e.target.value)}
            onKeyDown={e=>e.key==="Enter"&&login()}
            type="email" placeholder={isSeller?"seller@company.com":"installer@company.com"}
            style={{width:"100%",background:C.navyMid,border:`1px solid ${C.navyBord}`,borderRadius:8,padding:"9px 12px",color:"#EAF0FF",fontSize:12,marginBottom:12,boxSizing:"border-box"}}
            onFocus={e=>e.target.style.borderColor=accent} onBlur={e=>e.target.style.borderColor=C.navyBord}/>

          <label style={{display:"block",fontSize:10,color:C.muted,fontWeight:500,marginBottom:5}}>Password</label>
          <input value={pass} onChange={e=>setPass(e.target.value)}
            onKeyDown={e=>e.key==="Enter"&&login()}
            type="password" placeholder="••••••••"
            style={{width:"100%",background:C.navyMid,border:`1px solid ${C.navyBord}`,borderRadius:8,padding:"9px 12px",color:"#EAF0FF",fontSize:12,marginBottom:18,boxSizing:"border-box"}}
            onFocus={e=>e.target.style.borderColor=accent} onBlur={e=>e.target.style.borderColor=C.navyBord}/>

          <button onClick={login} disabled={loading}
            style={{width:"100%",padding:"12px",borderRadius:9,background:loading?"#1C1C28":`linear-gradient(135deg,${accent},${acDim})`,color:loading?"#4A5A6A":"#0A0F1E",fontFamily:"'Space Grotesk'",fontSize:13,fontWeight:700,border:`1px solid ${accent}`,cursor:loading?"default":"pointer",transition:"all .2s"}}>
            {loading ? "Signing in…" : `Sign In to ${title}`}
          </button>
        </div>

        <p style={{textAlign:"center",marginTop:16,fontSize:11,color:C.dim}}>
          Don't have an account?{" "}
          <span style={{color:accent,cursor:"pointer"}} onClick={()=>nav(isSeller?"e-seller-signup":"e-installer-signup")}>
            Apply to join →
          </span>
        </p>
      </div>
    </div>
  );
};


const GOOGLE_MAPS_KEY = (typeof window !== "undefined" && window.__GG_MAPS_KEY__) || "";

const geoApi = {
  autocomplete: async (q, session) => {
    const r = await fetch(`/api/geo/search?q=${encodeURIComponent(q)}&session=${session}`,{credentials:"include"});
    const d = await r.json(); return d.predictions||[];
  },
  placeDetails: async (placeId) => {
    const r = await fetch(`/api/geo/search?placeId=${placeId}`,{credentials:"include"});
    const d = await r.json(); return d.place||null;
  },
  validate: async (address) => {
    const r = await fetch("/api/geo/validate",{method:"POST",headers:{"Content-Type":"application/json"},credentials:"include",body:JSON.stringify({address})});
    return r.json();
  },
  detectUtility: async (zip) => {
    const r = await fetch(`/api/geo/utility-territory?zip=${zip}`,{credentials:"include"});
    return r.json();
  },
  nearbyInstallers: async (params) => {
    const q = new URLSearchParams(params).toString();
    const r = await fetch(`/api/geo/installers?${q}`,{credentials:"include"});
    return r.json();
  },
  reverseGeocode: async (lat,lng) => {
    const r = await fetch(`/api/geo/reverse?lat=${lat}&lng=${lng}&utility=true`,{credentials:"include"});
    return r.json();
  },
  intelligence: async (params) => {
    const q = new URLSearchParams(Object.entries(params).filter(([,v])=>v)).toString();
    const r = await fetch(`/api/geo/intelligence?${q}`,{credentials:"include"});
    return r.json();
  },
};

function AddressAutocomplete({value,onChange,onSelect,onValidated,placeholder,accentColor,showValidation,detectUtility,style}) {
  placeholder = placeholder||"Enter your home address";
  showValidation = showValidation!==false;
  detectUtility  = detectUtility||false;
  const accent   = accentColor||C.teal;
  const extStyle = style||{};
  const [query,setQuery]     = useState(value||"");
  const [preds,setPreds]     = useState([]);
  const [open,setOpen]       = useState(false);
  const [loading,setLoading] = useState(false);
  const [validating,setValid]= useState(false);
  const [result,setResult]   = useState(null);
  const [utility,setUtility] = useState(null);
  const sessionRef = useRef((Math.random()*1e9|0).toString(36));
  const timerRef   = useRef(null);
  const wrapRef    = useRef(null);

  useEffect(()=>{
    const h=(e)=>{if(!wrapRef.current?.contains(e.target))setOpen(false);};
    document.addEventListener("mousedown",h);
    return()=>document.removeEventListener("mousedown",h);
  },[]);

  useEffect(()=>{
    if(query.length<3){setPreds([]);return;}
    clearTimeout(timerRef.current);
    timerRef.current=setTimeout(async()=>{
      setLoading(true);
      try{const p=await geoApi.autocomplete(query,sessionRef.current);setPreds(p);}
      catch{}finally{setLoading(false);}
    },300);
  },[query]);

  const handleSelect = async (pred) => {
    const addr = pred.description||pred.formatted||"";
    setQuery(addr); setPreds([]); setOpen(false);
    onChange?.(addr);
    try{
      const place = await geoApi.placeDetails(pred.place_id||"");
      if(place){
        if(showValidation){
          setValid(true);
          try{const v=await geoApi.validate(addr);setResult(v);onValidated?.(v);}
          catch{}finally{setValid(false);}
        }
        if(detectUtility&&place.zip){
          try{const u=await geoApi.detectUtility(place.zip);setUtility(u?.utility||null);}
          catch{}
        }
        onSelect?.(place);
      }
    }catch{}
  };

  const isValid   = result?.valid===true;
  const isInvalid = result?.valid===false;

  return(
    <div ref={wrapRef} style={{position:"relative",...extStyle}}>
      <div style={{position:"relative",display:"flex",alignItems:"center"}}>
        <input value={query}
          onChange={e=>{setQuery(e.target.value);onChange?.(e.target.value);setOpen(true);setResult(null);}}
          onFocus={()=>query.length>=3&&setPreds(p=>p)}
          placeholder={placeholder}
          style={{width:"100%",padding:"11px 14px",background:"#1C2330",border:`1.5px solid ${isValid?C.green:isInvalid?"#FF4D6A":accent+"40"}`,
            borderRadius:10,color:"#E8EEFF",fontSize:13,outline:"none",boxSizing:"border-box",transition:"border-color .2s"}}/>
        {loading&&<div style={{position:"absolute",right:12,width:14,height:14,borderRadius:"50%",border:`2px solid ${accent}30`,borderTopColor:accent,animation:"spin .8s linear infinite"}}/>}
        {validating&&<div style={{position:"absolute",right:12,fontSize:10,color:accent}}>...</div>}
        {isValid&&<div style={{position:"absolute",right:12,color:C.green,fontSize:13}}>&#10003;</div>}
      </div>
      {open&&preds.length>0&&(
        <div style={{position:"absolute",top:"100%",left:0,right:0,marginTop:4,background:"#1C2330",border:`1px solid ${accent}30`,borderRadius:10,zIndex:200,overflow:"hidden",boxShadow:"0 8px 32px rgba(0,0,0,0.4)"}}>
          {preds.slice(0,5).map((p,i)=>(
            <div key={i} onClick={()=>handleSelect(p)}
              style={{padding:"10px 14px",cursor:"pointer",fontSize:12,color:"#E8EEFF",borderBottom:i<preds.length-1?"1px solid #252535":"none",transition:"background .1s"}}
              onMouseEnter={e=>e.currentTarget.style.background=accent+"12"}
              onMouseLeave={e=>e.currentTarget.style.background="transparent"}>
              <div style={{fontWeight:500}}>{p.main_text||p.description}</div>
              {p.secondary_text&&<div style={{fontSize:10,color:"#8890A8",marginTop:2}}>{p.secondary_text}</div>}
            </div>
          ))}
          <div style={{padding:"6px 14px",fontSize:10,color:"#4A5570",textAlign:"right"}}>Powered by Google</div>
        </div>
      )}
      {utility&&(
        <div style={{marginTop:6,padding:"6px 12px",background:`${accent}0a`,border:`1px solid ${accent}20`,borderRadius:8,fontSize:10,color:accent}}>
          Utility: {utility.name||utility.short}
        </div>
      )}
    </div>
  );
};


function LocationButton({onLocate,color=C.teal}) {
  const [loading,setLoading]=useState(false);
  const [denied,setDenied]=useState(false);

  const locate=async()=>{
    if(!navigator.geolocation){alert("Geolocation not supported.");return;}
    setLoading(true);setDenied(false);
    navigator.geolocation.getCurrentPosition(async(pos)=>{
      try{
        const r=await geoApi.reverseGeocode(pos.coords.latitude,pos.coords.longitude);
        onLocate?.(r);
      }catch{}finally{setLoading(false);}
    },(err)=>{setLoading(false);setDenied(true);},
    {timeout:10000,maximumAge:300000});
  };

  return(
    <button onClick={locate}
      style={{display:"flex",alignItems:"center",gap:5,padding:"5px 10px",borderRadius:7,
        background:`${color}10`,border:`1px solid ${color}25`,
        fontSize:10,color:color,cursor:"pointer",transition:"all .15s"}}
      onMouseEnter={e=>e.currentTarget.style.background=color+"20"}
      onMouseLeave={e=>e.currentTarget.style.background=color+"10"}>
      {loading
        ?<div style={{width:10,height:10,borderRadius:"50%",border:`1.5px solid ${color}30`,borderTopColor:color,animation:"spin .7s linear infinite"}}/>
        :<svg width="12" height="12" viewBox="0 0 24 24" fill="none"><circle cx="12" cy="12" r="3" fill={color}/><path d="M12 2v3M12 19v3M2 12h3M19 12h3" stroke={color} strokeWidth="2" strokeLinecap="round"/></svg>
      }
      {denied?"Location denied":"Use my location"}
    </button>
  );
};


function GeoIntelligenceCard({data, accentColor}) {
  if(!data||data.error) return null;
  const col = accentColor||C.teal;
  const {utility,iso,incentives,vpp} = data;
  return(
    <div style={{marginTop:10,background:"#0F1520",border:`1px solid ${col}20`,borderRadius:12,overflow:"hidden",fontSize:11}}>
      {utility&&(
        <div style={{padding:"10px 14px",borderBottom:"1px solid #1A2236",display:"flex",alignItems:"center",gap:8,flexWrap:"wrap"}}>
          <Icon name="zap" size={12} color={col}/>
          <span style={{fontWeight:600,color:"#E8EEFF"}}>{utility.name||utility.shortName}</span>
          {utility.vppReady&&<span style={{fontSize:9,padding:"2px 6px",borderRadius:5,background:`${C.green}14`,color:C.green,fontWeight:700}}>VPP Ready</span>}
          {iso&&<span style={{fontSize:10,color:"#5A6A7A"}}>· {iso.iso}</span>}
        </div>
      )}
      {incentives&&incentives.total>0&&(
        <div style={{padding:"8px 14px",borderBottom:"1px solid #1A2236"}}>
          <span style={{color:C.gold,fontWeight:600}}>{incentives.total} incentives</span>
          {incentives.estimatedValue?.estimatedTotal>0&&<span style={{color:"#6A7A8A"}}> · ~${incentives.estimatedValue.estimatedTotal.toLocaleString()} est.</span>}
        </div>
      )}
      {vpp&&vpp.eligible&&(
        <div style={{padding:"8px 14px"}}>
          <span style={{color:col,fontWeight:600}}>VPP eligible</span>
          {vpp.estimatedAnnualEarnings?.high>0&&<span style={{color:C.green}}> · ${vpp.estimatedAnnualEarnings.low}–${vpp.estimatedAnnualEarnings.high}/yr est.</span>}
        </div>
      )}
    </div>
  );
};


