function AILogo({size="sm"}) {
  const svgSize = size==="lg" ? 36 : 26;
  const textSize = size==="lg" ? 20 : 15;
  return(
    <div style={{display:"flex",alignItems:"center",gap:9}}>
      <svg width={svgSize} height={svgSize} viewBox="0 0 80 80">
        <defs>
          <linearGradient id="alg1" x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stopColor={C.teal}/>
            <stop offset="100%" stopColor="#7B5CF5"/>
          </linearGradient>
        </defs>
        <path d="M40,8 L66,20 L66,44 C66,57 54,68 40,72 C26,68 14,57 14,44 L14,20 Z" fill="url(#alg1)" opacity="0.15"/>
        <path d="M40,8 L66,20 L66,44 C66,57 54,68 40,72 C26,68 14,57 14,44 L14,20 Z" fill="none" stroke="url(#alg1)" strokeWidth="2"/>
        <line x1="26" y1="35" x2="54" y2="35" stroke={C.teal} strokeWidth="1.5" opacity="0.5"/>
        <line x1="26" y1="45" x2="54" y2="45" stroke={C.teal} strokeWidth="1.5" opacity="0.5"/>
        <line x1="33" y1="26" x2="33" y2="56" stroke={C.teal} strokeWidth="1.5" opacity="0.5"/>
        <line x1="47" y1="26" x2="47" y2="56" stroke={C.teal} strokeWidth="1.5" opacity="0.5"/>
        <circle cx="40" cy="40" r="6" fill={C.gold} opacity="0.9"/>
        <path d="M38,40 L40.5,35 L40.5,40 L43,40 L40.5,45 L40.5,40 Z" fill={AI.bg}/>
      </svg>
      <div>
        <div style={{fontFamily:"'Space Grotesk'",fontWeight:700,fontSize:textSize,lineHeight:1}}>
          <span style={{background:"linear-gradient(135deg,#00D4AA,#7B5CF5)",WebkitBackgroundClip:"text",WebkitTextFillColor:"transparent",backgroundClip:"text"}}>GridGuide</span><span style={{color:C.gold}}>.ai</span>
        </div>
      </div>
    </div>
  );
};

