function PageHeader({nav, title, subtitle, chip, chipColor, backTo="ai-home", backLabel="Home", children}) {
  const {isMobile} = useBP();
  return(
    <div style={{maxWidth:1060,margin:"0 auto",padding:isMobile?"32px 20px 0":"52px 20px 0"}}>
      {/* Back / breadcrumb */}
      <button onClick={()=>nav(backTo)}
        style={{display:"inline-flex",alignItems:"center",gap:7,marginBottom:20,background:"none",border:"none",cursor:"pointer",
          color:AI.muted,fontSize:12,padding:"6px 10px",borderRadius:8,transition:"all .15s"}}
        onMouseEnter={e=>{e.currentTarget.style.background=AI.card;e.currentTarget.style.color=AI.text;}}
        onMouseLeave={e=>{e.currentTarget.style.background="none";e.currentTarget.style.color=AI.muted;}}>
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
          <polyline points="15 18 9 12 15 6"/>
        </svg>
        {backLabel}
      </button>
      {/* Title block */}
      {(title||chip)&&(
        <div style={{marginBottom:32}}>
          {chip&&<Chip color={chipColor||C.teal} style={{marginBottom:12}}>{chip}</Chip>}
          {title&&<h1 style={{fontFamily:"'Space Grotesk'",fontSize:isMobile?28:44,fontWeight:800,letterSpacing:"-.04em",marginBottom:subtitle?10:0,color:AI.text}}>{title}</h1>}
          {subtitle&&<p style={{color:AI.muted,fontSize:isMobile?14:16,lineHeight:1.9,maxWidth:540}}>{subtitle}</p>}
          {children}
        </div>
      )}
    </div>
  );
};

