function EnergyContact({nav}) {
  const {isMobile} = useBP();
  const [form,setForm] = React.useState({name:"",email:"",subject:"",message:""});
  const [sent,setSent] = React.useState(false);
  const upd = (k,v) => setForm(p=>({...p,[k]:v}));
  return(
    <div style={{background:C.navy,color:C.text,paddingTop:62}}>
      <EnergyPageHeader nav={nav} backTo="e-home" backLabel="Home"/>
      <section style={{padding:"72px 24px 60px",maxWidth:860,margin:"0 auto"}}>
        <Chip color={C.teal} style={{marginBottom:14}}>Contact Us</Chip>
        <h1 style={{fontFamily:"'Space Grotesk'",fontSize:isMobile?30:44,fontWeight:800,letterSpacing:"-.03em",marginBottom:10}}>
          Get in Touch
        </h1>
        <p style={{color:C.muted,fontSize:15,lineHeight:1.8,marginBottom:48,maxWidth:560}}>
          Questions about GridGuide? We'd love to hear from you. Our team typically responds within one business day.
        </p>
        {sent ? (
          <div style={{textAlign:"center",padding:"60px 20px",background:`${C.teal}08`,border:`1px solid ${C.teal}30`,borderRadius:20}}>
            <div style={{fontSize:46,marginBottom:16}}>✅</div>
            <h2 style={{fontFamily:"'Space Grotesk'",fontSize:21,fontWeight:700,marginBottom:8}}>Message Sent!</h2>
            <p style={{color:C.muted,fontSize:13}}>We'll get back to you at {form.email} within 1 business day.</p>
            <Btn variant="teal" style={{marginTop:24}} onClick={()=>setSent(false)}>Send Another Message</Btn>
          </div>
        ) : (
          <div style={{display:"grid",gridTemplateColumns:isMobile?"1fr":"1fr 1fr",gap:48}}>
            <div>
              {[
                {label:"Name",key:"name",placeholder:"Your full name"},
                {label:"Email",key:"email",placeholder:"you@example.com"},
                {label:"Subject",key:"subject",placeholder:"How can we help?"},
              ].map(f=>(
                <div key={f.key} style={{marginBottom:18}}>
                  <label style={{display:"block",fontSize:11,fontWeight:600,color:C.muted,marginBottom:6,textTransform:"uppercase",letterSpacing:".06em"}}>{f.label}</label>
                  <input value={form[f.key]} onChange={e=>upd(f.key,e.target.value)} placeholder={f.placeholder}
                    style={{width:"100%",padding:"12px 14px",background:"#0D1520",border:"1px solid #1E2D3D",borderRadius:10,color:C.text,fontSize:13,boxSizing:"border-box"}}/>
                </div>
              ))}
              <div style={{marginBottom:24}}>
                <label style={{display:"block",fontSize:11,fontWeight:600,color:C.muted,marginBottom:6,textTransform:"uppercase",letterSpacing:".06em"}}>Message</label>
                <textarea value={form.message} onChange={e=>upd("message",e.target.value)} rows={5} placeholder="Tell us more..."
                  style={{width:"100%",padding:"12px 14px",background:"#0D1520",border:"1px solid #1E2D3D",borderRadius:10,color:C.text,fontSize:13,boxSizing:"border-box",resize:"vertical"}}/>
              </div>
              <Btn variant="teal" onClick={()=>{if(form.name&&form.email&&form.message)setSent(true);}}>
                Send Message <Icon name="arrow" size={14} color={C.navy}/>
              </Btn>
            </div>
            <div>
              {[
                {icon:"mail",label:"General Inquiries",val:"hello@gridguide.ai"},
                {icon:"tool",label:"Installer Partners",val:"installers@gridguide.ai"},
                {icon:"store",label:"Seller Partnerships",val:"sellers@gridguide.ai"},
                {icon:"shield",label:"Support",val:"support@gridguide.ai"},
                {icon:"map",label:"Headquarters",val:"Austin, TX 78701"},
              ].map(item=>(
                <div key={item.label} style={{display:"flex",gap:14,alignItems:"flex-start",padding:"16px 0",borderBottom:`1px solid ${C.navyBord}`}}>
                  <div style={{width:36,height:36,borderRadius:9,background:`${C.teal}14`,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
                    <Icon name={item.icon} size={16} color={C.teal}/>
                  </div>
                  <div>
                    <div style={{fontSize:10,color:C.muted,fontWeight:600,textTransform:"uppercase",letterSpacing:".06em",marginBottom:3}}>{item.label}</div>
                    <div style={{fontSize:13,color:C.text}}>{item.val}</div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </section>
    </div>
  );
};

function AICareers({nav}) {
  const {isMobile} = useBP();

  const [applyRole, setApplyRole] = useState(null); // null = closed, string = role name
  const [form, setForm] = useState({name:"",email:"",phone:"",linkedin:"",resumeUrl:"",coverLetter:"",source:""});
  const [submitting, setSubmitting] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const [formErr, setFormErr] = useState("");

  const openApply = (role) => {
    setApplyRole(role);
    setForm({name:"",email:"",phone:"",linkedin:"",coverLetter:"",source:""});
    setSubmitted(false); setFormErr("");
  };
  const closeApply = () => { setApplyRole(null); setSubmitted(false); setFormErr(""); };

  const submitApplication = async () => {
    if(!form.name.trim()||!form.email.trim()){
      setFormErr("Name and email are required."); return;
    }
    setSubmitting(true); setFormErr("");
    try{
      const r = await fetch("/api/careers",{
        method:"POST", credentials:"include",
        headers:{"Content-Type":"application/json"},
        body: JSON.stringify({ role: applyRole, ...form }),
      });
      const d = await r.json();
      if(!r.ok){ setFormErr(d.error||"Submission failed. Please try again."); }
      else { setSubmitted(true); }
    }catch(e){ setFormErr("Network error — please try again."); }
    setSubmitting(false);
  };

  const jobs = [
    {
      team:"Business Development",
      role:"Head of Installer Partnerships",
      loc:"Remote (U.S.)",
      type:"Full-Time",
      exp:"5+ Years",
      desc:"Lead GridGuide's national installer network by developing strategic partnerships, expanding our installer ecosystem, and helping thousands of homeowners connect with trusted energy professionals.",
    },
  ];

  const teamColors = {Engineering:C.teal,Product:C.gold,"Business Development":C.green,Design:C.purple,Operations:C.blue};

  const benefits = [
    {icon:"🌎", title:"Remote-Friendly",         desc:"Work from anywhere in the United States where eligible."},
    {icon:"💰", title:"Competitive Compensation", desc:"Salary and performance-based incentives designed to reward your impact."},
    {icon:"📈", title:"Growth Opportunities",     desc:"Help build a rapidly growing energy technology platform."},
    {icon:"⚡", title:"Mission-Driven",           desc:"Create technology that helps homeowners save money while supporting a smarter electric grid."},
  ];

  const steps = [
    "Submit your application.",
    "Initial conversation with our team.",
    "Role-specific interview(s).",
    "Final interview.",
    "Offer and onboarding.",
  ];

  return(
    <div style={{background:AI.bg,color:AI.text,minHeight:"100vh",paddingTop:62}}>

      {/* ── Application Modal ── */}
      {applyRole&&(
        <div style={{position:"fixed",inset:0,background:"rgba(0,0,0,.82)",zIndex:1001,display:"flex",alignItems:"flex-start",justifyContent:"center",padding:"20px",overflowY:"auto"}}
          onClick={e=>{ if(e.target===e.currentTarget) closeApply(); }}>
          <div style={{background:AI.card,border:"1px solid "+AI.border,borderRadius:18,width:"100%",maxWidth:560,margin:"40px 0"}}>
            {/* Header */}
            <div style={{padding:"18px 22px",borderBottom:"1px solid "+AI.border,display:"flex",alignItems:"center",justifyContent:"space-between"}}>
              <div>
                <div style={{fontFamily:"'Space Grotesk'",fontWeight:700,fontSize:14,color:AI.text}}>
                  {submitted ? "Application Received!" : "Apply"}
                </div>
                <div style={{fontSize:11,color:AI.muted,marginTop:2}}>{applyRole}</div>
              </div>
              <button onClick={closeApply} style={{background:"#252D3E",border:"none",borderRadius:8,width:30,height:30,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center"}}>
                <Icon name="x" size={14} color="#8890A8"/>
              </button>
            </div>

            {submitted ? (
              <div style={{padding:"40px 28px",textAlign:"center"}}>
                <div style={{width:56,height:56,borderRadius:"50%",background:C.teal+"14",border:"2px solid "+C.teal,display:"flex",alignItems:"center",justifyContent:"center",margin:"0 auto 16px"}}>
                  <Icon name="check" size={26} color={C.teal}/>
                </div>
                <div style={{fontFamily:"'Space Grotesk'",fontSize:16,fontWeight:700,color:AI.text,marginBottom:8}}>Application submitted!</div>
                <p style={{fontSize:13,color:AI.muted,marginBottom:24,lineHeight:1.7}}>
                  We've received your application for <strong style={{color:AI.text}}>{applyRole}</strong>. Our team will review it and reach out if there's a match. Thank you for your interest in GridGuide.
                </p>
                <Btn variant="teal" onClick={closeApply}>Close</Btn>
              </div>
            ) : (
              <div style={{padding:"24px 28px"}}>
                <div style={{display:"grid",gridTemplateColumns:isMobile?"1fr":"1fr 1fr",gap:14,marginBottom:14}}>
                  {[
                    {key:"name",      label:"Full Name *",       placeholder:"Jane Smith",               type:"text"},
                    {key:"email",     label:"Email Address *",   placeholder:"jane@example.com",          type:"email"},
                    {key:"phone",     label:"Phone (optional)",  placeholder:"+1 (555) 000-0000",         type:"tel"},
                    {key:"linkedin",  label:"LinkedIn (optional)",placeholder:"https://linkedin.com/in/…", type:"url"},
                    {key:"resumeUrl",  label:"Resume Link (optional)",placeholder:"https://drive.google.com/… or Dropbox, etc.", type:"url"},
                  ].map(f=>(
                    <div key={f.key}>
                      <label style={{fontSize:10,fontWeight:600,color:AI.muted,display:"block",marginBottom:5,textTransform:"uppercase",letterSpacing:".05em"}}>{f.label}</label>
                      <input type={f.type} value={form[f.key]} onChange={e=>setForm(p=>({...p,[f.key]:e.target.value}))}
                        placeholder={f.placeholder}
                        style={{width:"100%",padding:"9px 12px",background:"#0D1526",border:"1px solid "+AI.border,borderRadius:8,color:AI.text,fontSize:12,boxSizing:"border-box"}}/>
                    </div>
                  ))}
                </div>
                <p style={{fontSize:10,color:AI.dim,marginBottom:14,lineHeight:1.6}}>
                  For your resume, paste a shareable link from Google Drive, Dropbox, OneDrive, or a portfolio site. Make sure sharing is set to "Anyone with the link."
                </p>
                <div style={{marginBottom:14}}>
                  <label style={{fontSize:10,fontWeight:600,color:AI.muted,display:"block",marginBottom:5,textTransform:"uppercase",letterSpacing:".05em"}}>Cover Letter (optional)</label>
                  <textarea value={form.coverLetter} onChange={e=>setForm(p=>({...p,coverLetter:e.target.value}))}
                    placeholder="Tell us about yourself, your experience, and why you're excited about GridGuide…"
                    rows={5} maxLength={5000}
                    style={{width:"100%",padding:"9px 12px",background:"#0D1526",border:"1px solid "+AI.border,borderRadius:8,color:AI.text,fontSize:12,boxSizing:"border-box",resize:"vertical",fontFamily:"'Inter',sans-serif",lineHeight:1.7}}/>
                  <div style={{fontSize:9,color:AI.dim,textAlign:"right",marginTop:2}}>{form.coverLetter.length}/5000</div>
                </div>
                <div style={{marginBottom:18}}>
                  <label style={{fontSize:10,fontWeight:600,color:AI.muted,display:"block",marginBottom:5,textTransform:"uppercase",letterSpacing:".05em"}}>How did you hear about us? (optional)</label>
                  <select value={form.source} onChange={e=>setForm(p=>({...p,source:e.target.value}))}
                    style={{width:"100%",padding:"9px 12px",background:"#0D1526",border:"1px solid "+AI.border,borderRadius:8,color:form.source?AI.text:AI.muted,fontSize:12}}>
                    <option value="">Select one…</option>
                    {["LinkedIn","Job Board","Friend / Referral","Google Search","GridGuide Website","Social Media","Other"].map(s=>(
                      <option key={s} value={s}>{s}</option>
                    ))}
                  </select>
                </div>
                {formErr&&<div style={{fontSize:11,color:"#FF4D6A",marginBottom:14,padding:"8px 12px",background:"#FF4D6A14",borderRadius:8}}>{formErr}</div>}
                <div style={{display:"flex",gap:10}}>
                  <Btn variant="ghost" onClick={closeApply} style={{flex:1}}>Cancel</Btn>
                  <Btn variant="teal" disabled={submitting||!form.name.trim()||!form.email.trim()} onClick={submitApplication} style={{flex:2}}>
                    {submitting?"Submitting…":"Submit Application"}
                  </Btn>
                </div>
                <p style={{fontSize:10,color:AI.dim,marginTop:12,lineHeight:1.6,textAlign:"center"}}>
                  Your information is used only for hiring purposes and is never shared with third parties.
                </p>
              </div>
            )}
          </div>
        </div>
      )}

      {/* ── 1. Hero ── */}
      <section style={{maxWidth:860,margin:"0 auto",padding:isMobile?"48px 20px 40px":"80px 32px 56px"}}>
        <Chip color={C.teal} style={{marginBottom:14}}>Careers</Chip>
        <h1 style={{fontFamily:"'Space Grotesk'",fontSize:isMobile?28:46,fontWeight:900,letterSpacing:"-.03em",lineHeight:1.1,marginBottom:16}}>
          Build the Energy Future<br/><span style={{color:C.teal}}>with Us.</span>
        </h1>
        <p style={{color:AI.muted,fontSize:isMobile?13:15,lineHeight:1.85,marginBottom:28,maxWidth:600}}>
          GridGuide is building technology that helps homeowners monitor, optimize, and earn from their home energy systems. Join our team as we create a smarter, more connected energy future.
        </p>
        <div style={{display:"flex",gap:12,flexWrap:"wrap"}}>
          <Btn variant="teal" onClick={()=>{ const el=document.getElementById("gg-open-roles"); if(el) el.scrollIntoView({behavior:"smooth"}); }}>
            View Open Positions
          </Btn>
          <Btn variant="ghost" onClick={()=>openApply("Open Application")}>
            Submit an Open Application
          </Btn>
        </div>
      </section>

      {/* ── 2. Why GridGuide ── */}
      <section style={{background:`${C.teal}06`,borderTop:`1px solid ${C.teal}15`,borderBottom:`1px solid ${C.teal}15`}}>
        <div style={{maxWidth:860,margin:"0 auto",padding:isMobile?"40px 20px":"56px 32px"}}>
          <h2 style={{fontFamily:"'Space Grotesk'",fontSize:isMobile?20:26,fontWeight:800,marginBottom:16}}>Why Work at GridGuide?</h2>
          <p style={{color:AI.muted,fontSize:13,lineHeight:1.9,marginBottom:14,maxWidth:680}}>
            We're building technology that helps homeowners better understand and manage their energy. By connecting utilities, solar, batteries, EVs, and Virtual Power Plant programs into one platform, we're working toward a more resilient, efficient, and customer-focused energy future.
          </p>
          <p style={{color:AI.muted,fontSize:13,lineHeight:1.9,maxWidth:680}}>
            At GridGuide, you'll help shape products that make clean energy more accessible while working alongside people who are passionate about innovation, sustainability, and solving real-world energy challenges.
          </p>
        </div>
      </section>

      {/* ── 3. Benefits ── */}
      <section style={{maxWidth:960,margin:"0 auto",padding:isMobile?"40px 20px":"56px 32px"}}>
        <h2 style={{fontFamily:"'Space Grotesk'",fontSize:isMobile?18:22,fontWeight:800,marginBottom:24,textAlign:"center"}}>What We Offer</h2>
        <div style={{display:"grid",gridTemplateColumns:isMobile?"1fr 1fr":"repeat(3,1fr)",gap:14}}>
          {benefits.map(b=>(
            <div key={b.title} style={{background:AI.card,border:"1px solid "+AI.border,borderRadius:16,padding:"22px 18px",textAlign:"center"}}>
              <div style={{fontSize:28,marginBottom:10}}>{b.icon}</div>
              <div style={{fontFamily:"'Space Grotesk'",fontSize:13,fontWeight:700,color:AI.text,marginBottom:8}}>{b.title}</div>
              <p style={{fontSize:11,color:AI.muted,lineHeight:1.7,margin:0}}>{b.desc}</p>
            </div>
          ))}
        </div>
      </section>

      {/* ── 4. Open Positions ── */}
      <section id="gg-open-roles" style={{maxWidth:860,margin:"0 auto",padding:isMobile?"0 20px 40px":"0 32px 56px"}}>
        <h2 style={{fontFamily:"'Space Grotesk'",fontSize:isMobile?20:26,fontWeight:800,marginBottom:6}}>Open Positions</h2>
        <p style={{color:AI.muted,fontSize:12,marginBottom:24,lineHeight:1.7}}>All roles are remote within the United States unless otherwise noted.</p>
        <div style={{display:"flex",flexDirection:"column",gap:14}}>
          {jobs.map(j=>(
            <div key={j.role} style={{background:AI.card,border:"1px solid "+AI.border,borderRadius:16,overflow:"hidden",transition:"border-color .2s"}}
              onMouseEnter={e=>e.currentTarget.style.borderColor=teamColors[j.team]||C.teal}
              onMouseLeave={e=>e.currentTarget.style.borderColor=AI.border}>
              <div style={{padding:"20px 24px 0"}}>
                <div style={{display:"flex",gap:8,flexWrap:"wrap",marginBottom:10}}>
                  <span style={{fontSize:10,padding:"3px 9px",borderRadius:6,background:`${teamColors[j.team]||C.teal}18`,color:teamColors[j.team]||C.teal,fontWeight:700,letterSpacing:".04em"}}>{j.team.toUpperCase()}</span>
                  <span style={{fontSize:10,padding:"3px 9px",borderRadius:6,background:AI.border+"50",color:AI.muted}}>{j.type}</span>
                </div>
                <div style={{fontFamily:"'Space Grotesk'",fontSize:isMobile?16:18,fontWeight:800,color:AI.text,marginBottom:6}}>{j.role}</div>
                <div style={{display:"flex",gap:16,flexWrap:"wrap",marginBottom:12}}>
                  {[["map","Location",j.loc],["users","Experience",j.exp]].map(([icon,label,val])=>(
                    <div key={label} style={{display:"flex",alignItems:"center",gap:5,fontSize:11,color:AI.muted}}>
                      <Icon name={icon} size={11} color={AI.dim}/>{label}: <strong style={{color:AI.text}}>{val}</strong>
                    </div>
                  ))}
                </div>
                <p style={{fontSize:12,color:AI.muted,lineHeight:1.75,marginBottom:20}}>{j.desc}</p>
              </div>
              <div style={{borderTop:"1px solid "+AI.border,padding:"14px 24px",display:"flex",justifyContent:"flex-end"}}>
                <Btn variant="teal" size="sm" onClick={()=>openApply(j.role)}>
                  Apply Now <Icon name="arrow" size={12} color={C.navy}/>
                </Btn>
              </div>
            </div>
          ))}
        </div>
      </section>

      {/* ── 5. Open Application ── */}
      <section style={{maxWidth:860,margin:"0 auto",padding:isMobile?"0 20px 40px":"0 32px 56px"}}>
        <div style={{background:`${C.purple}08`,border:`1px solid ${C.purple}20`,borderRadius:16,padding:isMobile?"24px":"32px 36px"}}>
          <div style={{fontFamily:"'Space Grotesk'",fontSize:15,fontWeight:700,color:AI.text,marginBottom:8}}>Don't See the Right Role?</div>
          <p style={{fontSize:12,color:AI.muted,lineHeight:1.7,marginBottom:20}}>We'd still love to hear from you. Submit an open application and we'll contact you if a future opportunity matches your experience and interests.</p>
          <Btn variant="ghost" onClick={()=>openApply("Open Application")}>
            Submit an Open Application →
          </Btn>
        </div>
      </section>

      {/* ── 6. Hiring Process ── */}
      <section style={{maxWidth:860,margin:"0 auto",padding:isMobile?"0 20px 40px":"0 32px 56px"}}>
        <h2 style={{fontFamily:"'Space Grotesk'",fontSize:isMobile?18:22,fontWeight:800,marginBottom:24}}>What to Expect</h2>
        <div style={{display:"flex",flexDirection:"column",gap:0}}>
          {steps.map((step,i)=>(
            <div key={i} style={{display:"flex",gap:16,alignItems:"flex-start"}}>
              <div style={{display:"flex",flexDirection:"column",alignItems:"center",flexShrink:0}}>
                <div style={{width:30,height:30,borderRadius:"50%",background:`${C.teal}14`,border:`2px solid ${C.teal}40`,display:"flex",alignItems:"center",justifyContent:"center",fontFamily:"'Space Grotesk'",fontSize:12,fontWeight:800,color:C.teal}}>
                  {i+1}
                </div>
                {i<steps.length-1&&<div style={{width:2,height:28,background:`${C.teal}20`,margin:"2px 0"}}/>}
              </div>
              <p style={{fontSize:13,color:AI.muted,lineHeight:1.7,paddingTop:5}}>{step}</p>
            </div>
          ))}
        </div>
      </section>

      {/* ── 7. Mission CTA ── */}
      <section style={{maxWidth:860,margin:"0 auto",padding:isMobile?"0 20px 72px":"0 32px 96px"}}>
        <div style={{background:`linear-gradient(135deg,${AI.card},${C.teal}08)`,border:`1px solid ${C.teal}20`,borderRadius:20,padding:isMobile?"28px 24px":"44px 48px",textAlign:"center"}}>
          <h2 style={{fontFamily:"'Space Grotesk'",fontSize:isMobile?20:28,fontWeight:900,marginBottom:12,lineHeight:1.2}}>
            Help Build the Future<br/>of Home Energy.
          </h2>
          <p style={{color:AI.muted,fontSize:13,lineHeight:1.85,maxWidth:520,margin:"0 auto 24px"}}>
            Every homeowner deserves simple, intelligent tools to manage their energy. Join us in building the platform that connects homeowners, installers, utilities, and clean energy technologies.
          </p>
          <div style={{display:"flex",gap:12,justifyContent:"center",flexWrap:"wrap"}}>
            <Btn variant="teal" onClick={()=>{ const el=document.getElementById("gg-open-roles"); if(el) el.scrollIntoView({behavior:"smooth"}); }}>
              Explore Careers
            </Btn>
            <Btn variant="ghost" onClick={()=>nav("ai-contact")}>
              Contact Us
            </Btn>
          </div>
        </div>
      </section>

    </div>
  );
};

