          <Bar data={[4.2,3.8,5.1,4.9,6.2,5.8,4.4,3.9,5.3,6.1,5.7,4.8,3.6,4.1]} labels={[4.2,3.8,5.1,4.9,6.2,5.8,4.4,3.9,5.3,6.1,5.7,4.8,3.6,4.1].map((_,i)=>`${6+i}h`)} colors={[C.teal]} height={100}/>
