function AIAssistant({onClose}) {
  const {isMobile}=useBP();
  const [msgs,setMsgs]=useState([{role:"assistant",text:"Hi! I'm your GridGuide AI. Ask me anything about your energy system.\n\nTry: \"Should I add a battery?\", \"When should I charge my EV?\", or \"Which rebates am I eligible for?\""}]);
  const [input,setInput]=useState("");
  const [loading,setLoading]=useState(false);
  const endRef=useRef();
  const system=`You are GridGuide's AI Energy Assistant — expert, concise, and action-oriented. User's live data:
- Solar: 4.2 kW producing, Enphase IQ8+, 18 panels, 28.4 kWh today
- Battery: Tesla Powerwall 3, 78% SOC, 13.5 kWh, self-powered mode
- EV: ChargePoint Home Flex, Ford F-150 Lightning, 62% SOC, charging at 7.2 kW
- Smart Panel: Span, 3.4 kW load, 32 circuits
- Thermostat: Ecobee, 72°F, cooling, 2.1 kW HVAC
- Utility: PG&E, E-TOU-C tariff, peak $0.48/kWh (4–9 PM), off-peak $0.16/kWh
- Bill: $12.40 this month (was $280 before solar), saving $267.60/month
- VPP event tomorrow 4–8 PM, estimated $8.40 earning from battery discharge
- Eligible rebates: CA TECH Clean CA $3,000, SGIP $1,000, utility battery incentive $500
- Home Energy Score: 92/100
Keep answers 2–4 sentences, reference their actual data, one clear action.`;
  const send=async()=>{
    if(!input.trim()||loading)return;
    const q=input;
    setMsgs(m=>[...m,{role:"user",text:q}]);
    setInput("");setLoading(true);
    try{
      const res=await fetch("/api/ai/chat",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({message:q,history:msgs.slice(1).map(m=>({role:m.role,content:m.text})),context:"gridguide-energy"})});
      const data=await res.json();
      const reply=data.reply||data.content?.find(c=>c.type==="text")?.text||"Unable to respond right now.";
      setMsgs(m=>[...m,{role:"assistant",text:reply}]);
    }catch{setMsgs(m=>[...m,{role:"assistant",text:"Connection issue. Please try again."}]);}
    setLoading(false);
    setTimeout(()=>endRef.current?.scrollIntoView({behavior:"smooth"}),80);
  };
  const sugs=["Should I add a battery?","When should I charge my EV?","Am I on the right rate plan?","Which rebates am I eligible for?","What's my home energy score?"];
  return(
    <div style={{position:"fixed",bottom:isMobile?0:22,right:isMobile?0:22,width:isMobile?"100%":380,height:isMobile?"80vh":530,background:"#181E28",border:`1px solid ${C.teal}30`,borderRadius:isMobile?"14px 14px 0 0":14,display:"flex",flexDirection:"column",boxShadow:`0 20px 60px #000, 0 0 40px ${C.teal}10`,zIndex:1000,animation:"slide-down .3s ease"}}>
      <div style={{padding:"13px 17px",borderBottom:"1px solid #2A2A40",display:"flex",justifyContent:"space-between",alignItems:"center",background:`linear-gradient(135deg,${C.teal}10,${C.purple}08)`,borderRadius:isMobile?"14px 14px 0 0":"14px 14px 0 0"}}>
        <div style={{display:"flex",gap:10,alignItems:"center"}}>
          <div style={{width:30,height:30,borderRadius:9,background:`linear-gradient(135deg,${C.teal},${C.purple})`,display:"flex",alignItems:"center",justifyContent:"center"}}><Icon name="bot" size={15} color="#fff"/></div>
          <div><div style={{fontFamily:"'Space Grotesk'",fontWeight:700,fontSize:12,color:"#E8EEFF"}}>AI Energy Assistant</div><div style={{fontSize:10,color:C.teal,display:"flex",alignItems:"center",gap:4}}><span className="live" style={{width:5,height:5}}/>Live data connected</div></div>
        </div>
        <button onClick={onClose} style={{color:"#7A94B8",fontSize:16,padding:4}}><Icon name="x" size={16} color="#444"/></button>
      </div>
      <div style={{flex:1,overflowY:"auto",padding:13,display:"flex",flexDirection:"column",gap:10}}>
        {msgs.map((m,i)=>(
          <div key={i} style={{display:"flex",gap:8,flexDirection:m.role==="user"?"row-reverse":"row",alignItems:"flex-start"}}>
            {m.role==="assistant"&&<div style={{width:26,height:26,borderRadius:7,background:`${C.teal}14`,border:`1px solid ${C.teal}28`,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}><Icon name="zap" size={12} color={C.teal}/></div>}
            <div style={{maxWidth:"83%",padding:"9px 13px",borderRadius:m.role==="user"?"12px 4px 12px 12px":"4px 12px 12px 12px",background:m.role==="user"?`linear-gradient(135deg,${C.teal},${C.tealDim})`:"#1C2330",color:m.role==="user"?C.navy:"#ccc",fontSize:12,lineHeight:1.7,whiteSpace:"pre-wrap"}}>
              {m.text}
            </div>
          </div>
        ))}
        {loading&&<div style={{display:"flex",gap:8,alignItems:"center"}}><div style={{width:26,height:26,borderRadius:7,background:`${C.teal}14`,display:"flex",alignItems:"center",justifyContent:"center"}}><Icon name="zap" size={12} color={C.teal}/></div><div style={{padding:"9px 13px",background:"#1C2330",borderRadius:"4px 12px 12px 12px",display:"flex",gap:6,alignItems:"center"}}><Spinner sz={11}/><span style={{fontSize:10,color:"#7A94B8"}}>Analyzing your energy…</span></div></div>}
        <div ref={endRef}/>
      </div>
      {msgs.length===1&&<div style={{padding:"0 13px 8px",display:"flex",gap:5,flexWrap:"wrap"}}>{sugs.map(s=><button key={s} onClick={()=>setInput(s)} style={{padding:"4px 10px",background:"#1C2330",border:"1px solid #2A2A40",borderRadius:20,fontSize:10,color:"#8FA3C0",cursor:"pointer"}}>{s}</button>)}</div>}
      <div style={{padding:"10px 13px",borderTop:"1px solid #1a1a1a",display:"flex",gap:7}}>
        <input value={input} onChange={e=>setInput(e.target.value)} onKeyDown={e=>e.key==="Enter"&&send()} placeholder="Ask about your energy…" style={{flex:1,background:"#1C2330",border:`1.5px solid #1a1a1a`,borderRadius:9,padding:"9px 12px",color:"#E8EEFF",fontSize:12}} onFocus={e=>e.target.style.borderColor=C.teal} onBlur={e=>e.target.style.borderColor="#1a1a1a"}/>
        <button onClick={send} disabled={!input.trim()||loading} style={{width:37,height:37,borderRadius:9,background:input.trim()?`linear-gradient(135deg,${C.teal},${C.tealDim})`:"#1F2A3C",color:input.trim()?C.navy:"#333",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0,transition:"all .18s"}}><Icon name="arrow" size={14} color={input.trim()?C.navy:"#333"}/></button>
      </div>
    </div>
  );
};

function DualSitesApp({onEnterPortal=null}) {
  const [page,setPage] = useState(()=>{
    const pending = typeof window!=="undefined" ? window.__ggPendingPage : null;
    if(pending){ delete window.__ggPendingPage; return pending; }
    return "e-home";
  });
  const [user,setUser] = useState(null);
  const [switcherHidden,setSwitcherHidden] = useState(false);
  const [aiOpen,setAiOpen] = useState(false);

  useEffect(() => {
    fetch("/api/users/me", { credentials: "include" })
      .then(r => r.ok ? r.json() : null)
      .then(d => {
        if (!d?.user) return;
        setUser(homeownerDefaults(d.user));
        const params = new URLSearchParams(window.location.search);
        const checkout  = params.get("checkout");
        const tab       = params.get("tab");
        const utility   = params.get("utility");   // "success" | "denied" | "error"
        const gbMethod  = params.get("method");     // "green_button" if GBC callback

        if (utility === "success") {
          setPage("ai-dashboard");
          const meters = params.get("meters");
          setTimeout(() => {
            document.dispatchEvent(new CustomEvent("gg-tab", { detail: "utility" }));
            if (gbMethod === "green_button" && meters) {
              document.dispatchEvent(new CustomEvent("gg-notify", { detail: {
                type: "success",
                message: `🟢 Green Button connected! GridGuide is now syncing your real meter data from your utility.`,
              }}));
            }
          }, 0);
          window.history.replaceState({}, "", window.location.pathname);
        } else if (utility === "denied" || utility === "error") {
          setPage("ai-dashboard");
          setTimeout(() => {
            document.dispatchEvent(new CustomEvent("gg-tab", { detail: "utility" }));
            document.dispatchEvent(new CustomEvent("gg-notify", { detail: {
              type: "error",
              message: "Utility connection was not completed. You can try again from your Utility tab.",
            }}));
          }, 0);
          window.history.replaceState({}, "", window.location.pathname);
        } else if (checkout || tab) {
          setPage("ai-dashboard");
          const targetTab = tab || "orders";
          setTimeout(() => document.dispatchEvent(new CustomEvent("gg-tab", { detail: targetTab })), 0);
          window.history.replaceState({}, "", window.location.pathname);
        }
      })
      .catch(() => {});
  }, []);

  useEffect(()=>{
    if(typeof window === "undefined") return;
    if(window.google?.maps?.places) return;
    const key = window.__GG_MAPS_KEY__ || "";
    if(!key) return; // Skip if no key configured — backend fallback handles it
    const script = document.createElement("script");
    script.src = `https://maps.googleapis.com/maps/api/js?key=${key}&libraries=places&loading=async`;
    script.async = true;
    script.defer = true;
    document.head.appendChild(script);
  },[]);

  const nav = useCallback((p) => {
    setPage(p);
    try{window.scrollTo({top:0});}catch(e){}
  },[]);

  const isEnergy = page.startsWith("e-") || page==="login";
  const isAI = page.startsWith("ai-");

  const SiteSwitcher = ({hidden, setHidden}) => {
    const [swipe, setSwipe] = useState(null);

    const handleSwitch = (target, targetIsEnergy) => {
      const alreadyHere = targetIsEnergy ? isEnergy : isAI;
      if (alreadyHere) { setHidden(true); return; }

      setSwipe(target);
      setHidden(true);
      setTimeout(() => {
        setSwipe(null);
        if (targetIsEnergy) {
          nav("e-home");
        } else {
          nav(user ? "ai-dashboard" : "ai-home");
        }
      }, 320);
    };

    return (
      <>
        {/* Tab — slides to edge when panel is hidden, acts as a toggle */}
        <button
          onClick={()=>setHidden(h=>!h)}
          style={{
            position:"fixed",
            bottom:32,
            left:hidden?0:-56,
            zIndex:500,
            width:24,
            height:48,
            background:"rgba(18,18,24,0.97)",
            backdropFilter:"blur(20px)",
            border:"1px solid rgba(0,212,170,0.25)",
            borderLeft:"none",
            borderRadius:"0 8px 8px 0",
            display:"flex",alignItems:"center",justifyContent:"center",
            cursor:"pointer",
            transition:"left .4s cubic-bezier(.4,0,.2,1)",
            boxShadow:"3px 0 16px rgba(0,212,170,0.12)",
          }}
          aria-label={hidden?"Open site switcher":"Close site switcher"}
        >
          <span style={{
            fontSize:12,
            color:"#00D4AA",
            animation: hidden ? "arrowPulse 1.1s ease-in-out infinite" : "none",
            display:"block",lineHeight:1,
            transform: hidden ? "none" : "rotate(180deg)",
            transition:"transform .3s",
          }}>›</span>
        </button>

        {/* Main panel */}
        <div style={{
          position:"fixed",
          bottom:24,
          left:hidden?-240:24,
          zIndex:501,
          display:"flex",
          flexDirection:"column",
          gap:5,
          alignItems:"flex-start",
          transition:hidden
            ?"left .35s cubic-bezier(.55,0,1,.45)"
            :"left .4s cubic-bezier(0,0,.2,1)",
        }}>
          <div style={{fontSize:9,color:"#44475A",letterSpacing:".08em",fontWeight:600,textTransform:"uppercase",paddingLeft:2}}>Switch Site</div>
          <div style={{
            background:"rgba(18,18,24,0.97)",
            backdropFilter:"blur(20px)",
            border:"1px solid rgba(255,255,255,0.06)",
            borderRadius:12,
            padding:"5px",
            boxShadow:"0 8px 40px rgba(0,0,0,0.4)",
            position:"relative",
            overflow:"hidden",
            minWidth:156,
          }}>
            {/* Active pill */}
            <div style={{
              position:"absolute",left:5,right:5,
              height:"calc(50% - 5px)",borderRadius:8,
              background:isEnergy?"rgba(245,200,66,0.12)":"rgba(0,212,170,0.10)",
              border:isEnergy?"1px solid rgba(245,200,66,0.25)":"1px solid rgba(0,212,170,0.22)",
              top:isEnergy?5:"calc(50% + 2px)",
              transition:"top .28s cubic-bezier(.4,0,.2,1),background .28s,border .28s",
              pointerEvents:"none",zIndex:0,
            }}/>

            {[
              {id:"energy", label:"Energy Site",  color:C.gold, active:isEnergy, isEnergy:true},
              {id:"ai",     label:"GridGuide.ai", color:C.teal, active:isAI,     isEnergy:false},
            ].map(btn=>(
              <button key={btn.id}
                onClick={()=>handleSwitch(btn.id, btn.isEnergy)}
                style={{
                  position:"relative",zIndex:1,display:"flex",alignItems:"center",gap:8,
                  width:"100%",padding:"7px 12px",borderRadius:8,background:"transparent",
                  border:"none",cursor:btn.active?"default":"pointer",overflow:"hidden",
                  opacity:btn.active?1:0.85,
                }}>
                {/* Shimmer sweep — only on inactive buttons being clicked */}
                <div style={{
                  position:"absolute",inset:0,borderRadius:8,
                  background:`linear-gradient(90deg,transparent,${btn.color}28,transparent)`,
                  transform:swipe===btn.id?"translateX(100%)":"translateX(-100%)",
                  transition:swipe===btn.id?"transform .32s ease":"none",
                  pointerEvents:"none",
                }}/>
                <span style={{
                  width:7,height:7,borderRadius:"50%",flexShrink:0,display:"inline-block",
                  background:btn.active?btn.color:"#2E2E3A",
                  transition:"background .2s,transform .25s",
                  transform:swipe===btn.id?"translateX(6px)":"translateX(0)",
                }}/>
                <span style={{
                  fontFamily:"'Space Grotesk'",fontSize:10,fontWeight:600,whiteSpace:"nowrap",
                  color:btn.active?btn.color:"#555",
                  transition:"transform .25s",
                  transform:swipe===btn.id?"translateX(4px)":"translateX(0)",
                }}>{btn.label}</span>
                {btn.active && (
                  <span style={{marginLeft:"auto",fontSize:9,color:btn.color,fontWeight:700,opacity:0.7}}>●</span>
                )}
                {swipe===btn.id&&(
                  <span style={{marginLeft:"auto",fontSize:10,color:btn.color,fontWeight:700}}>→</span>
                )}
              </button>
            ))}
          </div>
        </div>
      </>
    );
  };

  const renderPage = () => {
    switch(page){
      case"e-home":         return <EnergyHome nav={nav}/>;
      case"e-about":        return <EnergyAbout nav={nav}/>;
      case"ai-about":       return <EnergyAbout nav={nav}/>;
      case"ai-careers":       return <AICareers nav={nav}/>;
      case"e-blog":         return <EnergyBlog nav={nav}/>;
      case"ai-blog":        return <EnergyBlog nav={nav}/>;
      case"e-consumer":     return <EnergyConsumer nav={nav}/>;
      case"e-how-it-works": return <EnergyHowItWorks nav={nav}/>;
      case"e-installers":   return <EnergyInstallers nav={nav}/>;
      case"e-installer-pricing": return <EnergyInstallerPricing nav={nav}/>;
      case"e-rebates":      return <EnergyRebates nav={nav}/>;
      case"e-vpp":          return <EnergyVPP nav={nav}/>;
      case"e-marketplace":  return <EnergyMarket nav={nav} user={user}/>;
      case"e-installer-signup": return <EnergyInstallerSignup nav={nav}/>;
      case"e-privacy":          return <AIPrivacy nav={nav}/>;
      case"e-terms":            return <AITerms nav={nav}/>;
      case"e-seller-signup":    return <EnergySellerSignup nav={nav}/>;
      case"e-installer-login":  return <PortalGateway nav={nav} type="installer" onEnterPortal={onEnterPortal}/>;
      case"e-seller-login":     return <PortalGateway nav={nav} type="seller" onEnterPortal={onEnterPortal}/>;
      case"e-enterprise-login": return <EnterpriseGateway nav={nav} onEnterPortal={onEnterPortal}/>;
      case"e-business":         return <EnergyBusiness nav={nav}/>;
      case"e-ai":           return <EnergyAIPage nav={nav}/>;
      case"ai-home":        return <AIHome nav={nav}/>;
      case"ai-features":    return <AIFeatures nav={nav}/>;
      case"ai-market":      return <AIMarketplace nav={nav} user={user}/>;
      case"ai-community":   return <AICommunity nav={nav}/>;
      case"ai-order-confirm": return <AIOrderConfirm nav={nav} user={user}/>;
      case"ai-rewards":       return <AIRewardsPage nav={nav} user={user}/>;
      case"ai-rebates":       return <AIRebates nav={nav} user={user}/>;
      case"ai-utilities":     return <AISupportedUtilities nav={nav}/>;
      case"ai-faq":           return <AIFeatures nav={nav}/>;
      case"ai-vpp":           return <AIVPPPage nav={nav} user={user}/>;
      case"e-contact":        return <EnergyContact nav={nav}/>;
      case"ai-contact":       return <EnergyContact nav={nav}/>;
      case"ai-pricing":       return <AIPricing nav={nav}/>;
      case"ai-docs":          return <APIDocs nav={nav}/>;
      case"ai-integrations":  return <AIIntegrations nav={nav}/>;
      case"ai-webhooks":      return <AIWebhooks nav={nav}/>;
      case"ai-status":        return <AIStatus nav={nav}/>;
      case"ai-changelog":     return <AIChangelog nav={nav}/>;
      case"ai-privacy":       return <AIPrivacy nav={nav}/>;
      case"ai-terms":         return <AITerms nav={nav}/>;
      case"ai-login":         return <AILogin nav={nav} setUser={setUser} onEnterPortal={onEnterPortal}/>;
      case"ai-signup":      return <AISignup nav={nav} setUser={setUser}/>;
      case"ai-dashboard":   return user?<AIDashboard user={user} nav={nav} setUser={setUser}/>:<AILogin nav={nav} setUser={setUser}/>;
      case"e-sellers":       return <EnergySellers nav={nav}/>;
      case"e-pricing":       return <EnergyPricing nav={nav}/>;
      case"e-impact":        return <EnergyCommunityImpact nav={nav}/>;
      default:              return page.startsWith("e-")?<EnergyHome nav={nav}/>:<AIHome nav={nav}/>;
    }
  };


  return(
    <>
      <GS/>

      {/* Nav — different for each site */}
      {isEnergy && <EnergyNav page={page} nav={nav} user={user} onEnterPortal={onEnterPortal}/>}
      {isAI     && <AINAv page={page} nav={nav} user={user} setUser={setUser} onEnterPortal={onEnterPortal}/>}

      {/* Page content */}
      <div style={{background:isEnergy?C.navy:AI.bg,minHeight:"100vh"}}>
        {renderPage()}
      </div>

      {/* AI floating button + chat (only on GridGuide.ai) */}
      {isAI && !aiOpen && (
        <button onClick={()=>setAiOpen(true)}
          style={{position:"fixed",bottom:90,right:24,width:48,height:48,borderRadius:"50%",background:`linear-gradient(135deg,${C.purple},#5a3fd4)`,color:"#fff",display:"flex",alignItems:"center",justifyContent:"center",boxShadow:`0 4px 20px ${C.purple}60`,zIndex:999,border:`1.5px solid ${C.purple}`,cursor:"pointer",transition:"transform .2s"}}
          onMouseEnter={e=>e.currentTarget.style.transform="scale(1.1)"} onMouseLeave={e=>e.currentTarget.style.transform="scale(1)"} title="AI Energy Assistant">
          <Icon name="bot" size={20} color="#fff"/>
        </button>
      )}
      {isAI && aiOpen && <AIAssistant onClose={()=>setAiOpen(false)}/>}

      {/* Site switcher (always visible for demo) */}
      <SiteSwitcher hidden={switcherHidden} setHidden={setSwitcherHidden}/>
    </>
  );
}


/* ── THEMES ─────────────────────────────────────────────────────────────────── */
const SELLER   = { bg:"#0F1014",surf:"#16171E",card:"#1C1D26",hi:"#22232E",bord:"#2E3040",accent:"#F5C842",acDim:"#C49A1A",text:"#F0F2FF",muted:"#8890A8",dim:"#4A4E60" };
const INSTALL  = { bg:"#0F1310",surf:"#161C17",card:"#1C241E",hi:"#222E25",bord:"#2E3E32",accent:"#00D4AA",acDim:"#009D7E",text:"#F0F2FF",muted:"#8890A8",dim:"#4A4E60" };
const ADMIN    = { bg:"#0F0F13",surf:"#16161C",card:"#1C1C24",hi:"#22222C",bord:"#2E2E3A",accent:"#FF4D6A",acDim:"#D43055",text:"#F0F2FF",muted:"#8890A8",dim:"#4A4E60" };

const css = `@import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@500;600;700&family=Inter:wght@400;500&family=JetBrains+Mono:wght@400&display=swap');
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0;}
body{font-family:'Inter',sans-serif;-webkit-font-smoothing:antialiased;}
button{cursor:pointer;border:none;outline:none;background:none;font-family:inherit;}
input,select,textarea{font-family:inherit;outline:none;border:none;}
::-webkit-scrollbar{width:4px;height:4px;}
::-webkit-scrollbar-thumb{background:#2E2E3A;border-radius:2px;}
@keyframes fade{from{opacity:0;transform:translateY(8px);}to{opacity:1;transform:translateY(0);}}
@keyframes spin{to{transform:rotate(360deg);}}
@keyframes pulse{0%,100%{opacity:1;}50%{opacity:.35;}}
@keyframes slide{from{transform:translateX(-100%);}to{transform:translateX(0);}}
.fade{animation:fade .4s ease both;}`;

const SH = { teal:"#00D4AA",gold:"#F5C842",red:"#FF4D6A",purple:"#7B5CF5",green:"#22C55E",blue:"#3B82F6",orange:"#F97316" };

/* ── RESPONSIVE ─────────────────────────────────────────────────────────────── */
const usePBP = () => {
  const [w,setW] = useState(typeof window!=="undefined"?window.innerWidth:1200);
  useEffect(()=>{ const f=()=>setW(window.innerWidth); window.addEventListener("resize",f); return()=>window.removeEventListener("resize",f); },[]);
  return {isMobile:w<640,isTablet:w<1024,w};
};

/* ── GLOBAL CSS ─────────────────────────────────────────────────────────────── */
const portalCss = `@import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@500;600;700&family=Inter:wght@400;500&family=JetBrains+Mono:wght@400&display=swap');
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0;}
body{font-family:'Inter',sans-serif;-webkit-font-smoothing:antialiased;}
button{cursor:pointer;border:none;outline:none;background:none;font-family:inherit;}
input,select,textarea{font-family:inherit;outline:none;border:none;}
::-webkit-scrollbar{width:4px;height:4px;}
::-webkit-scrollbar-thumb{background:#2E2E3A;border-radius:2px;}
@keyframes fade{from{opacity:0;transform:translateY(8px);}to{opacity:1;transform:translateY(0);}}
@keyframes spin{to{transform:rotate(360deg);}}
@keyframes pulse{0%,100%{opacity:1;}50%{opacity:.35;}}
@keyframes slide{from{transform:translateX(-100%);}to{transform:translateX(0);}}
.fade{animation:fade .4s ease both;}`;

