// ── InstMembership — Plan management ─────────────────────────────────────────
const InstMembership=({currentPlan="PRO",openModal})=>{
  const {isMobile}=useBP();
  const [confirm,setConfirm]=useState(null);
  return(
    <div>
      <h1 style={{fontFamily:"'Space Grotesk'",fontSize:isMobile?18:22,fontWeight:800,color:T_I.text,marginBottom:4}}>Membership</h1>
      <p style={{fontSize:11,color:T_I.muted,marginBottom:20}}>Manage your GridGuide Installer plan.</p>

      <div style={{display:"grid",gridTemplateColumns:isMobile?"1fr":"repeat(3,1fr)",gap:12,marginBottom:18}}>
        {Object.entries(INST_PLANS).map(([planId,plan])=>{
          const isCurrent = planId===currentPlan;
          return(
            <div key={planId} style={{background:T_I.card,border:`2px solid ${isCurrent?plan.color:T_I.bord}`,borderRadius:14,padding:"20px 18px",position:"relative"}}>
              {isCurrent&&<div style={{position:"absolute",top:-10,left:"50%",transform:"translateX(-50%)",background:plan.color,color:"#0A0F1E",fontSize:9,fontWeight:700,padding:"3px 10px",borderRadius:20,textTransform:"uppercase",whiteSpace:"nowrap"}}>Current Plan</div>}
              <div style={{fontFamily:"'Space Grotesk'",fontSize:16,fontWeight:800,color:plan.color,marginBottom:4}}>{plan.label}</div>
              <div style={{fontSize:20,fontWeight:700,color:T_I.text,marginBottom:2}}>{plan.price===0?"Free":`$${plan.price}/mo`}</div>
              <div style={{fontSize:10,color:T_I.muted,marginBottom:14}}>{plan.shareRate}% recurring commission</div>
              {plan.features?.map(f=>(
                <div key={f} style={{display:"flex",gap:7,fontSize:10,color:T_I.muted,padding:"3px 0"}}>
                  <Icon name="check" size={10} color={plan.color} style={{flexShrink:0,marginTop:1}}/>{f}
                </div>
              ))}
              {!isCurrent&&(
                <Btn full size="sm" variant="ghost" style={{marginTop:14,borderColor:plan.color,color:plan.color}}
                  onClick={()=>setConfirm(planId)}>
                  {parseInt(plan.price)>parseInt(INST_PLANS[currentPlan]?.price||0)?"Upgrade":"Downgrade"} to {plan.label}
                </Btn>
              )}
            </div>
          );
        })}
      </div>

      {confirm&&(
        <div style={{background:`${SH.gold}08`,border:`1px solid ${SH.gold}30`,borderRadius:12,padding:"16px 20px",marginBottom:14}}>
          <div style={{fontFamily:"'Space Grotesk'",fontSize:13,fontWeight:700,color:T_I.text,marginBottom:6}}>Confirm Plan Change</div>
          <p style={{fontSize:11,color:T_I.muted,marginBottom:12}}>
            Change to {INST_PLANS[confirm]?.label} plan? Your commission rate will update to {INST_PLANS[confirm]?.shareRate}% starting next billing cycle.
          </p>
          <div style={{display:"flex",gap:10}}>
            <Btn size="sm" variant="ghost" onClick={()=>setConfirm(null)}>Cancel</Btn>
            <Btn size="sm" variant="teal" onClick={()=>setConfirm(null)}>Confirm Change</Btn>
          </div>
        </div>
      )}

      <Card T={T_I} title="Billing">
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"10px 0",borderBottom:`1px solid ${T_I.bord}`}}>
          <span style={{fontSize:12,color:T_I.muted}}>Current plan</span>
          <span style={{fontSize:12,fontWeight:600,color:T_I.text}}>{INST_PLANS[currentPlan]?.label} — {INST_PLANS[currentPlan]?.price===0?"Free":`$${INST_PLANS[currentPlan]?.price}/mo`}</span>
        </div>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"10px 0",borderBottom:`1px solid ${T_I.bord}`}}>
          <span style={{fontSize:12,color:T_I.muted}}>Next billing date</span>
          <span style={{fontSize:12,color:T_I.text}}>Aug 1, 2026</span>
        </div>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"10px 0"}}>
          <span style={{fontSize:12,color:T_I.muted}}>Payment method</span>
          <span style={{fontSize:12,color:T_I.text}}>•••• 4242</span>
        </div>
        <div style={{marginTop:12,display:"flex",gap:10}}>
          <Btn size="sm" variant="ghost">Update Payment</Btn>
          <Btn size="sm" variant="ghost">Download Invoices</Btn>
        </div>
      </Card>
    </div>
  );
};

